impl ImportKey {
    pub fn new(info: ImportInfo, groups: Option<&ImportGroups>) -> Self {
        Self {
            group: groups.map_or(0, |groups| groups.index(&((&info).into()))),
            source: info.source,
            has_no_attributes: info.has_no_attributes,
            kind: info.kind,
            slot_index: info.slot_index,
